// Utility functions
export function getCarsByManufacturer(manufacturer: string): GT7Car[] {
  return GT7_CARS.filter(car => car.manufacturer === manufacturer);
}

export function getCarsByCategory(category: string): GT7Car[] {
  return GT7_CARS.filter(car => car.category === category);
}

export function getCarsByDrivetrain(drivetrain: string): GT7Car[] {
  return GT7_CARS.filter(car => car.drivetrain === drivetrain);
}

export function getCarsByPriceRange(min: number, max: number): GT7Car[] {
  return GT7_CARS.filter(car => car.price !== null && car.price >= min && car.price <= max);
}

export function getCarsByPPRange(min: number, max: number): GT7Car[] {
  return GT7_CARS.filter(car => car.pp >= min && car.pp <= max);
}

export function searchCars(query: string): GT7Car[] {
  const q = query.toLowerCase();
  return GT7_CARS.filter(car =>
    car.manufacturer.toLowerCase().includes(q) ||
    car.model.toLowerCase().includes(q) ||
    car.engine.toLowerCase().includes(q)
  );
}

export function getUniqueManufacturers(): string[] {
  const manufacturers = new Set(GT7_CARS.map(car => car.manufacturer));
  return Array.from(manufacturers).sort();
}

export function getUniqueCategories(): string[] {
  const categories = new Set(GT7_CARS.map(car => car.category).filter(c => c));
  return Array.from(categories).sort();
}

export function getUniqueDrivetrains(): string[] {
  const drivetrains = new Set(GT7_CARS.map(car => car.drivetrain));
  return Array.from(drivetrains).sort();
}

export function getUniqueAspirations(): string[] {
  const aspirations = new Set(GT7_CARS.map(car => car.aspiration));
  return Array.from(aspirations).sort();
}

export function getUniquePriceTypes(): string[] {
  const priceTypes = new Set(GT7_CARS.map(car => car.price_type));
  return Array.from(priceTypes).sort();
}

export function getStatistics() {
  return {
    totalCars: GT7_CARS.length,
    uniqueManufacturers: getUniqueManufacturers().length,
    ppRange: {
      min: Math.min(...GT7_CARS.map(c => c.pp)),
      max: Math.max(...GT7_CARS.map(c => c.pp)),
    },
    priceRange: {
      min: Math.min(...GT7_CARS.filter(c => c.price && c.price > 0).map(c => c.price!)),
      max: Math.max(...GT7_CARS.filter(c => c.price !== null).map(c => c.price!)),
    },
    yearRange: {
      min: Math.min(...GT7_CARS.filter(c => c.year !== null).map(c => c.year!)),
      max: Math.max(...GT7_CARS.filter(c => c.year !== null).map(c => c.year!)),
    },
  };
}
